**csv_stream.go:**
```go
package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -L. -lcsvstream
#include "csv_stream.h"
#include <stdlib.h>

typedef int (*csv_stream_callback)(const char*, size_t, int, void*);
*/
import "C"
import (
    "fmt"
    "sync"
    "unsafe"
)

type streamContext struct {
    dataCh  chan string
    errCh   chan error
    mu      sync.Mutex
    active  bool
}

//export csvCallback
func csvCallback(json *C.char, length C.size_t, status C.int, ctx unsafe.Pointer) {
    sc := (*streamContext)(ctx)
    sc.mu.Lock()
    defer sc.mu.Unlock()

    if !sc.active {
        return
    }

    if status != 0 {
        sc.errCh <- fmt.Errorf("stream error: status=%d", status)
        return
    }

    if json == nil {
        close(sc.dataCh)
        sc.active = false
        return
    }

    goStr := C.GoStringN(json, C.int(length))
    C.free(unsafe.Pointer(json))
    sc.dataCh <- goStr
}

func StartCSVStream(path string) (<-chan string, <-chan error) {
    dataCh := make(chan string, 10)
    errCh := make(chan error, 1)

    ctx := &streamContext{
        dataCh: dataCh,
        errCh:  errCh,
        active: true,
    }

    go func() {
        cPath := C.CString(path)
        defer C.free(unsafe.Pointer(cPath))

        C.csv_stream(cPath, C.csv_stream_callback(C.csvCallback), unsafe.Pointer(ctx))

        ctx.mu.Lock()
        if ctx.active {
            close(errCh)
        }
        ctx.mu.Unlock()
    }()

    return dataCh, errCh
}

func main() {
    dataCh1, errCh1 := StartCSVStream("file1.csv")
    dataCh2, errCh2 := StartCSVStream("file2.csv")

    var wg sync.WaitGroup
    wg.Add(2)

    go func() {
        defer wg.Done()
        for json := range dataCh1 {
            fmt.Println("File1:", json)
        }
        for err := range errCh1 {
            fmt.Println("File1 Error:", err)
        }
    }()

    go func() {
        defer wg.Done()
        for json := range dataCh2 {
            fmt.Println("File2:", json)
        }
        for err := range errCh2 {
            fmt.Println("File2 Error:", err)
        }
    }()

    wg.Wait()
}
```

## Why This Is Asked
Tests ability to bridge Go and C with callbacks, manage lifetimes, and avoid unsafe pointer passes.

## Key Concepts
- CGO callbacks and trampolines
- cgo.Handle for Go values across C boundaries
- Memory ownership and handle release
- Thread-safety when called from C across Go threads

## Complete Implementation

**C Header (stream.h):**
```c
typedef void (*cb_t)(int, void*);
void register_stream(cb_t cb, void* user);
void trampoline(int value, void* handle_ptr);
void unregister_stream(void);
```

**C Trampoline (stream.c):**
```c
#include "stream.h"
#include <stdint.h>

void trampoline(int value, void* handle_ptr) {
    uintptr_t handle = (uintptr_t)handle_ptr;
    // This calls back into Go via cgo.Handle
    extern void go_callback(int value, uintptr_t handle);
    go_callback(value, handle);
}
```

**Go Binding:**
```go
/*
#cgo LDFLAGS: -L. -lstream
#include "stream.h"
*/
import "C"
import "unsafe"

var activeStreams = make(map[uintptr]chan int)
var streamsMutex sync.RWMutex

//export go_callback
func go_callback(value C.int, handlePtr C.uintptr_t) {
    handle := uintptr(handlePtr)
    streamsMutex.RLock()
    if ch, exists := activeStreams[handle]; exists {
        select {
        case ch <- int(value):
        default:
            // Channel full, drop value
        }
    }
    streamsMutex.RUnlock()
}

func StartStream() (<-chan int, func()) {
    ch := make(chan int, 100)

    // Create wrapper function and handle
    done := make(chan struct{})
    handle := C.uintptr_t(C.NewHandle(done))

    streamsMutex.Lock()
    activeStreams[uintptr(handle)] = ch
    streamsMutex.Unlock()

    // Register with C trampoline
    C.register_stream((*[0]byte)(C.trampoline), unsafe.Pointer(handle))

    // Cleanup function
    cleanup := func() {
        C.unregister_stream()
        C.Delete(C.Handle(handle))

        streamsMutex.Lock()
        delete(activeStreams, uintptr(handle))
        streamsMutex.Unlock()

        close(ch)
    }

    return ch, cleanup
}

// Usage example:
func consumeStreams() {
    stream1, stop1 := StartStream()
    stream2, stop2 := StartStream()

    go func() {
        for val := range stream1 {
            fmt.Printf("Stream 1: %d\n", val)
        }
    }()

    go func() {
        for val := range stream2 {
            fmt.Printf("Stream 2: %d\n", val)
        }
    }()

    // Stop after some time
    time.Sleep(5 * time.Second)
    stop1()
    stop2()
}
```

